package openapi

import (
	"bytes"
	"fmt"
	"sort"
	"strconv"

	"go.yaml.in/yaml/v4"
)

// Header opens the generated file.
const Header = "# SPDX-License-Identifier: AGPL-3.0-or-later\n" +
	"# Generated by `just openapi` from the capability registry. Do not edit by hand.\n"

// topOrder is the order the document's top-level keys are written in; every
// other mapping is sorted, so the output depends on nothing but its content.
var topOrder = []string{"openapi", "info", "tags", "paths", "components"}

// Generate returns the OpenAPI document as YAML.
func Generate(root string) ([]byte, error) {
	doc, err := Build(root)
	if err != nil {
		return nil, err
	}
	return Encode(doc)
}

// Encode renders a document as YAML in a stable order.
func Encode(doc map[string]any) ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteString(Header)
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(node(doc, true)); err != nil {
		return nil, err
	}
	if err := enc.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// node converts a JSON value to a YAML node with sorted mappings.
func node(v any, top bool) *yaml.Node {
	switch v := v.(type) {
	case map[string]any:
		n := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
		for _, k := range keys(v, top) {
			n.Content = append(n.Content, scalar("!!str", k), node(v[k], false))
		}
		return n
	case []any:
		n := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, item := range v {
			n.Content = append(n.Content, node(item, false))
		}
		return n
	case []string:
		n := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, item := range v {
			n.Content = append(n.Content, scalar("!!str", item))
		}
		return n
	case string:
		return scalar("!!str", v)
	case bool:
		return scalar("!!bool", strconv.FormatBool(v))
	case float64:
		if v == float64(int64(v)) {
			return scalar("!!int", strconv.FormatInt(int64(v), 10))
		}
		return scalar("!!float", strconv.FormatFloat(v, 'g', -1, 64))
	case nil:
		return scalar("!!null", "null")
	default:
		return scalar("!!str", fmt.Sprint(v))
	}
}

// scalar builds one scalar node.
func scalar(tag, value string) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: tag, Value: value}
}

// keys orders a mapping's keys: sorted, with the top level led by topOrder.
func keys(m map[string]any, top bool) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	rank := func(k string) int {
		if !top {
			return 0
		}
		for i, t := range topOrder {
			if t == k {
				return i
			}
		}
		return len(topOrder)
	}
	sort.Slice(out, func(i, j int) bool {
		ri, rj := rank(out[i]), rank(out[j])
		if ri != rj {
			return ri < rj
		}
		return out[i] < out[j]
	})
	return out
}
